{
  "packet_id": "H6-T04-3",
  "claim_id": "C033",
  "status": "SUPPORTED",
  "claim": {
    "component_id": "C033.component",
    "value": "Deprioritize an explanation only when the observation could reasonably have detected its predicted effect.",
    "scope": "A necessary sensitivity condition for deprioritization, not a claim that sensitivity alone requires deprioritization.",
    "provenance": {
      "refs": [
        {
          "source_id": "P024",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "The span explicitly states the necessary sensitivity condition."
    }
  },
  "signal_basis": {
    "component_id": "C033.signal_basis",
    "value": "Gather evidence for and against competing explanations and update their relative plausibility. Failure to detect an effect can result from a small test, weak intervention, delivery failure or an insensitive outcome even when the proposed mechanism matters.",
    "scope": "Assessing whether observations provide grounds to lower an explanation's plausibility, particularly when its predicted effect is not detected.",
    "provenance": {
      "refs": [
        {
          "source_id": "P009",
          "role": "SUPPORT"
        },
        {
          "source_id": "P023",
          "role": "SUPPORT"
        },
        {
          "source_id": "P034",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "The cited spans establish evidence-based reprioritization and explicitly identify reasons nondetection may occur despite a relevant mechanism."
    }
  },
  "stated_empirical_relation": {
    "component_id": "C033.stated_empirical_relation",
    "value": "NOT_APPLICABLE",
    "scope": "NOT_APPLICABLE",
    "provenance": {
      "refs": [],
      "support_status": "SUFFICIENT",
      "rationale": "The judgment is SUPPORTED; no unresolved empirical relation is required for this necessary-condition claim."
    }
  },
  "rationale": "An observation's failure to reveal a predicted effect counts against an explanation only if the observation had a reasonable opportunity to detect that effect. The mapping explicitly acknowledges alternative reasons for nondetection. This licenses the stated sensitivity requirement without making sensitivity sufficient for deprioritization.",
  "uncertainty": "Whether any particular observation has adequate sensitivity remains context-dependent; the claim does not assert that this condition has already been established.",
  "anomalies": []
}
